      if (this.isFlat(a)) {
        const count = Math.min(source.length - offset, FLAT_END - a);
        source.copy(this.flat, a - FLAT_BASE, offset, offset + count);
        a = u32(a + count);
        offset += count;
        continue;
      }
      const pageOffset = a & PAGE_MASK;
      const count = Math.min(source.length - offset, PAGE_SIZE - pageOffset);
      source.copy(this.page(a, true), pageOffset, offset, offset + count);
      a = u32(a + count);
      offset += count;
    }
  }

  copyOut(address, length) {
    const result = Buffer.alloc(length);
    let a = u32(address);
    let offset = 0;
    while (offset < length) {
      if (this.isFlat(a)) {
        const count = Math.min(length - offset, FLAT_END - a);
        this.flat.copy(result, offset, a - FLAT_BASE, a - FLAT_BASE + count);
        a = u32(a + count);
        offset += count;
        continue;
      }
      const pageOffset = a & PAGE_MASK;
      const count = Math.min(length - offset, PAGE_SIZE - pageOffset);
      const page = this.page(a, false);
      if (page) page.copy(result, offset, pageOffset, pageOffset + count);
      a = u32(a + count);
      offset += count;
    }
    return result;
  }

  readCString(address, limit = 4096) {
    const bytes = [];
    let a = u32(address);
    for (let i = 0; i < limit; i++, a = u32(a + 1)) {
      const value = this.read8(a);
      if (value === 0) break;
      bytes.push(value);
    }
    return Buffer.from(bytes).toString('utf8');
  }
}

class HostFiles {
  constructor(memory) {
    this.memory = memory;
    this.nextFd = 3;
    this.files = new Map();
    this.frameCount = 0;
    this.halted = false;
    this.framesDir = path.join(ROOT, 'frames');
    this.files.set(0, { kind: 'stdin', position: 0 });
    this.files.set(1, { kind: 'stdout', position: 0 });
    this.files.set(2, { kind: 'stderr', position: 0 });
  }

  resolve(filePath) {
    if (filePath === 'doom.wad') return path.join(ROOT, 'doom.wad');
    if (filePath.startsWith('/')) return filePath;
    return path.resolve(ROOT, filePath);
  }

  open(filePath, flags, mode) { // eslint-disable-line no-unused-vars
    const access = flags & 3;
    let hostFlags;
    if (access === 0) hostFlags = fs.constants.O_RDONLY;
    else if (access === 1) hostFlags = fs.constants.O_WRONLY;
    else hostFlags = fs.constants.O_RDWR;
    if (flags & 64) hostFlags |= fs.constants.O_CREAT;
    if (flags & 128) hostFlags |= fs.constants.O_EXCL;
    if (flags & 512) hostFlags |= fs.constants.O_TRUNC;
    if (flags & 1024) hostFlags |= fs.constants.O_APPEND;

    try {
      const hostFd = fs.openSync(this.resolve(filePath), hostFlags, mode || 0o644);
      const fd = this.nextFd++;
      this.files.set(fd, {
        kind: 'file',
        hostFd,
        path: this.resolve(filePath),
        position: (flags & 1024) ? fs.fstatSync(hostFd).size : 0,
        append: Boolean(flags & 1024),
      });
      return fd;
    } catch (error) {
      return -errnoFor(error);
    }
  }

  read(fd, address, count) {
    const file = this.files.get(fd);
    if (!file) return -9;
    if (file.kind === 'stdin') return 0;
    if (file.kind !== 'file') return -22;
    const buffer = Buffer.alloc(Math.min(count >>> 0, 16 * 1024 * 1024));
    try {
      const read = fs.readSync(file.hostFd, buffer, 0, buffer.length, file.position);
      file.position += read;
      this.memory.copyIn(address, buffer.subarray(0, read));
      return read;
    } catch (error) {
      return -errnoFor(error);
    }
  }

  write(fd, address, count) {
    const file = this.files.get(fd);
    if (!file) return -9;
    if (file.kind === 'stdout' || file.kind === 'stderr') {
      const data = this.memory.copyOut(address, count >>> 0);
      if (file.kind === 'stdout') process.stdout.write(data);
      else process.stderr.write(data);
      return data.length;
    }
    if (file.kind !== 'file') return -22;
    const data = this.memory.copyOut(address, count >>> 0);
    try {
      const position = file.append ? null : file.position;
      const written = fs.writeSync(file.hostFd, data, 0, data.length, position);
      if (!file.append) file.position += written;
      else file.position = fs.fstatSync(file.hostFd).size;
      return written;
    } catch (error) {
      return -errnoFor(error);
    }
  }

  seek(fd, offset, whence) {
    const file = this.files.get(fd);
    if (!file || file.kind !== 'file') return -9;
    let position;
    try {
      if (whence === 0) position = offset;
      else if (whence === 1) position = file.position + offset;
      else if (whence === 2) position = fs.fstatSync(file.hostFd).size + offset;
      else return -22;
      if (position < 0) return -22;
      file.position = position;
      return position;
    } catch (error) {
      return -errnoFor(error);
    }
  }

  close(fd) {
    const file = this.files.get(fd);
    if (!file) return -9;
    if (file.kind === 'file') {
      try {
        fs.closeSync(file.hostFd);
        if (file.path === FRAME_PATH) {
          this.frameCount++;
          fs.mkdirSync(this.framesDir, { recursive: true });
          fs.copyFileSync(FRAME_PATH, path.join(this.framesDir, `frame-${String(this.frameCount).padStart(6, '0')}.bmp`));
          if (MAX_FRAMES > 0 && this.frameCount >= MAX_FRAMES) this.halted = true;
        }
      } catch (error) {
        return -errnoFor(error);
      }
    }
    this.files.delete(fd);
    return 0;
  }

  syscall(number, args) {
    switch (number >>> 0) {
      case 0: return this.read(args[0], args[1], args[2]);
      case 1: return this.write(args[0], args[1], args[2]);
      case 2: return this.open(this.memory.readCString(args[0]), args[1] | 0, args[2] >>> 0);
      case 3: return this.close(args[0]);
      case 8: return this.seek(args[0], i32(args[1]), args[2] | 0);
      case 35: return 0; // nanosleep: timing is intentionally deterministic.
      case 60: this.halted = true; return 0;
      case 74: return 0; // fsync
      case 82: return -38; // rename is not used by this port.
      case 83: return -38; // mkdir is not used by this port.
      case 87: return -38; // unlink is not used by this port.
      case 96: return 0; // gettimeofday is stubbed by the image.
      case 201: {
        const seconds = Math.floor(Date.now() / 1000) >>> 0;
        if (args[0]) this.memory.write32(args[0], seconds);
        return seconds;
      }
      default: return -38;
    }
  }
}

class MipsCpu {
  constructor(memory, host) {
    this.memory = memory;
    this.host = host;
    this.reg = new Uint32Array(32);
    this.freg = new Uint32Array(32);
    this.hi = 0;
    this.lo = 0;
    this.fcc0 = false;
    this.fcsr = 0;
    this.pc = 0;
    this.steps = 0;
    this.halted = false;
    this.reason = '';
    this.floatView = new DataView(new ArrayBuffer(8));
  }

  writeReg(index, value) {
    if (index !== 0) this.reg[index] = u32(value);
  }

  readWord(address) {
    return this.memory.read32(address);
  }

  writeWord(address, value) {
    this.memory.write32(address, value);
  }

  signedWord(address) {
    return i32(this.readWord(address));
  }

  setHalt(reason) {
    this.halted = true;
    this.reason = reason;
  }

  float32(bits) {
    this.floatView.setUint32(0, u32(bits), true);
    return this.floatView.getFloat32(0, true);
  }

  float32Bits(value) {
    this.floatView.setFloat32(0, Math.fround(value), true);
    return this.floatView.getUint32(0, true);
  }

  double(index) {
    this.floatView.setUint32(0, this.freg[index], true);
    this.floatView.setUint32(4, this.freg[index + 1], true);
    return this.floatView.getFloat64(0, true);
  }

  doubleBits(index, value) {
    this.floatView.setFloat64(0, value, true);
    this.freg[index] = this.floatView.getUint32(0, true);
    this.freg[index + 1] = this.floatView.getUint32(4, true);
  }

  cop1(instruction, pc) {
    const rs = (instruction >>> 21) & 31;
    const rt = (instruction >>> 16) & 31;
    const fs = (instruction >>> 11) & 31;
    const fd = (instruction >>> 6) & 31;
    const funct = instruction & 63;

    if (rs === 0) {
      this.writeReg(rt, this.freg[fs]);
      return null;
    }
    if (rs === 2) {
      this.writeReg(rt, fs === 31 ? this.fcsr : 0);
      return null;
    }
    if (rs === 4) {
      this.freg[fs] = this.reg[rt];
      return null;
    }
    if (rs === 6) {
      if (fs === 31) this.fcsr = this.reg[rt];
      return null;
    }
    if (rs === 7) {
      this.freg[fs + 1] = this.reg[rt];
      return null;
    }
    if (rs === 8) {
      const target = u32(pc + 4 + (sign16(instruction) << 2));
      const taken = rt === 1 ? this.fcc0 : !this.fcc0;
      return { branch: true, target: taken ? target : u32(pc + 8) };
    }

    if (rs === 16) { // single precision
      const left = this.float32(this.freg[fs]);
      const right = this.float32(this.freg[(instruction >>> 11) & 31]);
      switch (funct) {
        case 0: this.freg[fd] = this.float32Bits(left + right); return null;
        case 2: this.freg[fd] = this.float32Bits(left * right); return null;
        case 3: this.freg[fd] = this.float32Bits(left / right); return null;
        case 6: this.freg[fd] = this.freg[fs]; return null;
        case 7: this.freg[fd] = this.float32Bits(-left); return null;
        case 13: this.freg[fd] = u32(Math.trunc(left)); return null;
        case 17: if (this.fcc0) this.freg[fd] = this.freg[fs]; return null;
        case 48: this.fcc0 = left < right; return null;
        default: break;
      }
    } else if (rs === 17) { // double precision
      const left = this.double(fs);
      const right = this.double((instruction >>> 11) & 31);
      switch (funct) {
        case 6: this.doubleBits(fd, left); return null;
        case 7: this.doubleBits(fd, -left); return null;
        case 17: if (this.fcc0) this.doubleBits(fd, left); return null;
        case 52: this.fcc0 = left < right; return null;
        default: break;
      }
    } else if (rs === 20 && funct === 32) { // cvt.s.w
      this.freg[fd] = this.float32Bits(i32(this.freg[fs]));
      return null;
    }

    if (rs === 16 && funct === 33) { // cvt.d.s
      this.doubleBits(fd, this.float32(this.freg[fs]));
      return null;
    }

    throw new Error(`Unsupported COP1 instruction at 0x${pc.toString(16)}: 0x${instruction.toString(16)}`);
  }

  loadWordLeft(address, oldValue) {
    const a = u32(address);
    const k = a & 3;
    let value = oldValue >>> 0;
    for (let n = 0; n <= k; n++) {
      const shift = 24 - (n * 8);
      value = (value & ~(0xff << shift)) | (this.memory.read8(a - k + n) << shift);
    }
    return value >>> 0;
  }

  loadWordRight(address, oldValue) {
    const a = u32(address);
    const k = a & 3;
    let value = oldValue >>> 0;
    for (let n = 0; n <= 3 - k; n++) {
      const shift = n * 8;
      value = (value & ~(0xff << shift)) | (this.memory.read8(a + n) << shift);
    }
    return value >>> 0;
  }

  storeWordLeft(address, value) {
    const a = u32(address);
    const k = a & 3;
    const v = value >>> 0;
    for (let n = 0; n <= k; n++) {
      this.memory.write8(a - k + n, v >>> (24 - n * 8));
    }
  }

  storeWordRight(address, value) {
    const a = u32(address);
    const k = a & 3;
    const v = value >>> 0;
    for (let n = 0; n <= 3 - k; n++) {
      this.memory.write8(a - k + n, v >>> (n * 8));
    }
  }

  execute(pc, instruction, inDelaySlot) {
    const op = instruction >>> 26;
    const rs = (instruction >>> 21) & 31;
    const rt = (instruction >>> 16) & 31;
    const rd = (instruction >>> 11) & 31;
    const shamt = (instruction >>> 6) & 31;
    const funct = instruction & 63;
    const imm = instruction & 0xffff;
    const simm = sign16(imm);
    const rsValue = this.reg[rs];
    const rtValue = this.reg[rt];
    const branch = (taken) => ({
      branch: true,
      target: taken ? u32(pc + 4 + (simm << 2)) : u32(pc + 8),
    });

    switch (op) {
      case 0: {
        switch (funct) {
          case 0: this.writeReg(rd, rtValue << shamt); return null;
          case 2: {
            const rotated = rs !== 0 && shamt !== 0;
            this.writeReg(rd, rotated ? ((rtValue >>> shamt) | (rtValue << (32 - shamt))) : (rtValue >>> shamt));
            return null;
          }
          case 3: this.writeReg(rd, rtValue >> shamt); return null;
          case 4: this.writeReg(rd, rtValue << (rsValue & 31)); return null;
          case 6: this.writeReg(rd, (rtValue >>> (rsValue & 31))); return null;
          case 7: this.writeReg(rd, rtValue >> (rsValue & 31)); return null;
          case 8: return { branch: true, target: rsValue };
          case 9: {
            const link = pc + 8;
            this.writeReg(rd || 31, link);
            return { branch: true, target: rsValue };
          }
          case 10: if (rtValue === 0) this.writeReg(rd, rsValue); return null;
          case 11: if (rtValue !== 0) this.writeReg(rd, rsValue); return null;
          case 12: {
            const args = [this.reg[4], this.reg[5], this.reg[6], this.reg[7], this.reg[8], this.reg[9]];
            const result = this.host.syscall(this.reg[2], args);
            this.writeReg(2, result);
            if (this.host.halted) this.setHalt(this.host.frameCount ? 'first frame saved' : 'exit syscall');
            return null;
          }
          case 13: this.setHalt(`break at 0x${pc.toString(16)}`); return null;
          case 16: this.writeReg(rd, this.hi); return null;
          case 17: this.hi = rsValue; return null;
          case 18: this.writeReg(rd, this.lo); return null;
          case 19: this.lo = rsValue; return null;
          case 24: {
            const product = BigInt(i32(rsValue)) * BigInt(i32(rtValue));
            this.lo = Number(product & 0xffffffffn) >>> 0;
            this.hi = Number((product >> 32n) & 0xffffffffn) >>> 0;
            return null;
          }
          case 25: {
            const product = BigInt(rsValue) * BigInt(rtValue);
            this.lo = Number(product & 0xffffffffn) >>> 0;
            this.hi = Number((product >> 32n) & 0xffffffffn) >>> 0;
            return null;
          }
          case 26: {
            const divisor = i32(rtValue);
            const dividend = i32(rsValue);
            if (divisor === 0) {
              this.lo = dividend < 0 ? 1 : 0xffffffff;
              this.hi = rsValue;
            } else {
              this.lo = u32(Math.trunc(dividend / divisor));
              this.hi = u32(dividend % divisor);
            }
            return null;
          }
          case 27: {
            const divisor = rtValue;
            if (divisor === 0) {
              this.lo = 0xffffffff;
              this.hi = rsValue;
            } else {
              this.lo = Math.floor(rsValue / divisor) >>> 0;
              this.hi = (rsValue % divisor) >>> 0;
            }
            return null;
          }
          case 32: this.writeReg(rd, i32(rsValue) + i32(rtValue)); return null;
          case 33: this.writeReg(rd, rsValue + rtValue); return null;
          case 34: this.writeReg(rd, rsValue - rtValue); return null;
          case 35: this.writeReg(rd, rsValue - rtValue); return null;
          case 36: this.writeReg(rd, rsValue & rtValue); return null;
          case 37: this.writeReg(rd, rsValue | rtValue); return null;
          case 38: this.writeReg(rd, rsValue ^ rtValue); return null;
          case 39: this.writeReg(rd, ~(rsValue | rtValue)); return null;
          case 42: this.writeReg(rd, i32(rsValue) < i32(rtValue) ? 1 : 0); return null;
          case 43: this.writeReg(rd, rsValue < rtValue ? 1 : 0); return null;
          case 52:
            if (rsValue === rtValue) this.setHalt(`trap at 0x${pc.toString(16)}`);
            return null;
          default: break;
        }
        break;
      }
      case 1: {
        const condition = rt === 0 ? i32(rsValue) < 0 : i32(rsValue) >= 0;
        if (rt === 16 || rt === 17) this.writeReg(31, pc + 8);
        return branch(condition);
      }
      case 2: {
        const target = u32((pc + 4) & 0xf0000000 | ((instruction & 0x03ffffff) << 2));
        return { branch: true, target };
      }
      case 3: {
        this.writeReg(31, pc + 8);
        const target = u32((pc + 4) & 0xf0000000 | ((instruction & 0x03ffffff) << 2));
        return { branch: true, target };
      }
      case 4: return branch(rsValue === rtValue);
      case 5: return branch(rsValue !== rtValue);
      case 6: return branch(i32(rsValue) <= 0);
      case 7: return branch(i32(rsValue) > 0);
      case 8: this.writeReg(rt, i32(rsValue) + simm); return null;
      case 9: this.writeReg(rt, rsValue + simm); return null;
      case 10: this.writeReg(rt, i32(rsValue) < simm ? 1 : 0); return null;
      case 11: this.writeReg(rt, rsValue < u32(simm) ? 1 : 0); return null;
      case 12: this.writeReg(rt, rsValue & imm); return null;
      case 13: this.writeReg(rt, rsValue | imm); return null;
      case 14: this.writeReg(rt, rsValue ^ imm); return null;
      case 15: this.writeReg(rt, imm << 16); return null;
      case 28:
        if (funct === 2) this.writeReg(rd, Math.imul(rsValue, rtValue));
        else throw new Error(`Unsupported SPECIAL2 instruction at 0x${pc.toString(16)}`);
        return null;
      case 32: this.writeReg(rt, u32(this.memory.read8(rsValue + simm)) | 0xffffff00 * (this.memory.read8(rsValue + simm) & 0x80 ? 1 : 0)); return null;
      case 33: {
        const value = this.memory.read16(rsValue + simm);
        this.writeReg(rt, value | (value & 0x8000 ? 0xffff0000 : 0));
        return null;
      }
      case 34: this.writeReg(rt, this.loadWordLeft(rsValue + simm, rtValue)); return null;
      case 35: this.writeReg(rt, this.memory.read32(rsValue + simm)); return null;
      case 36: this.writeReg(rt, this.memory.read8(rsValue + simm)); return null;
      case 37: this.writeReg(rt, this.memory.read16(rsValue + simm)); return null;
      case 38: this.writeReg(rt, this.loadWordRight(rsValue + simm, rtValue)); return null;
      case 40: this.memory.write8(rsValue + simm, rtValue); return null;
      case 41: this.memory.write16(rsValue + simm, rtValue); return null;
      case 42: this.storeWordLeft(rsValue + simm, rtValue); return null;
      case 43: this.memory.write32(rsValue + simm, rtValue); return null;
      case 46: this.storeWordRight(rsValue + simm, rtValue); return null;
      case 49: this.freg[rt] = this.float32Bits(this.float32(this.memory.read32(rsValue + simm))); return null;
      case 53: {
        const address = u32(rsValue + simm);
        this.freg[rt] = this.memory.read32(address);
        this.freg[rt + 1] = this.memory.read32(address + 4);
        return null;
      }
      case 57: this.memory.write32(rsValue + simm, this.freg[rt]); return null;
      case 61: {
        const address = u32(rsValue + simm);
        this.memory.write32(address, this.freg[rt]);
        this.memory.write32(address + 4, this.freg[rt + 1]);
        return null;
      }
      case 17: return this.cop1(instruction, pc);
      case 31: {
        if (funct === 0) {
          const width = rd + 1;
          this.writeReg(rt, (rsValue >>> shamt) & (width === 32 ? 0xffffffff : ((1 << width) - 1)));
          return null;
        }
        if (funct === 4) {
          const width = rd - shamt + 1;
          const mask = width === 32 ? 0xffffffff : ((1 << width) - 1) << shamt;
          this.writeReg(rt, (rtValue & ~mask) | ((rsValue << shamt) & mask));
          return null;
        }
        if (funct === 32 && shamt === 16) {
          this.writeReg(rt, (rsValue << 24) >> 24);
          return null;
        }
        if (funct === 32 && shamt === 24) {
          this.writeReg(rt, (rsValue << 16) >> 16);
          return null;
        }
        if (funct === 32 && shamt === 2) {
          this.writeReg(rt, ((rsValue & 0x00ff00ff) << 8) | ((rsValue & 0xff00ff00) >>> 8));
          return null;
        }
        throw new Error(`Unsupported SPECIAL3 instruction at 0x${pc.toString(16)}: 0x${instruction.toString(16)}`);
      }
      case 16:
        throw new Error(`Unsupported COP0 instruction at 0x${pc.toString(16)}`);
      default:
        break;
    }

    throw new Error(`Unsupported MIPS instruction at 0x${pc.toString(16)}: 0x${instruction.toString(16)}`);
  }

  step() {
    const pc = this.pc >>> 0;
    const instruction = this.memory.read32(pc);
    this.steps++;
    const flow = this.execute(pc, instruction, false);
    this.reg[0] = 0;
    if (this.halted) return;
    if (flow && flow.branch) {
      const delayPc = u32(pc + 4);
      const delayInstruction = this.memory.read32(delayPc);
      this.steps++;
      this.execute(delayPc, delayInstruction, true);
      this.reg[0] = 0;
      if (!this.halted) this.pc = flow.target >>> 0;
    } else {
      this.pc = u32(pc + 4);
    }
  }

  run(entry) {
    this.pc = entry >>> 0;
    this.reg[29] = 0x7ff00000;
    this.reg[31] = 0;
    while (!this.halted) {
      if (this.steps >= MAX_INSTRUCTIONS) {
        this.setHalt(`instruction limit (${MAX_INSTRUCTIONS})`);
        break;
      }
      this.step();
    }
  }
}

function loadElf(filename, memory) {
  const image = fs.readFileSync(filename);
  if (image[0] !== 0x7f || image.toString('ascii', 1, 4) !== 'ELF') throw new Error('Not an ELF image');
  if (image[4] !== 1 || image[5] !== 1) throw new Error('Expected a little-endian ELF32 image');
  const read16 = offset => image.readUInt16LE(offset);
  const read32 = offset => image.readUInt32LE(offset);
  const entry = read32(24);
  const phoff = read32(28);
  const phentsize = read16(42);
  const phnum = read16(44);

  for (let i = 0; i < phnum; i++) {
    const offset = phoff + i * phentsize;
    const type = read32(offset);
    if (type !== 1) continue;
    const fileOffset = read32(offset + 4);
    const virtualAddress = read32(offset + 8);
    const fileSize = read32(offset + 16);
    if (fileSize) memory.copyIn(virtualAddress, image.subarray(fileOffset, fileOffset + fileSize));
  }
  return entry;
}

function main() {
  const memory = new Memory();
  const entry = loadElf(ELF_PATH, memory);
  const host = new HostFiles(memory);
  const cpu = new MipsCpu(memory, host);

  try {
    cpu.run(entry);
  } catch (error) {
    process.stderr.write(`vm.js stopped at PC 0x${cpu.pc.toString(16)} after ${cpu.steps} instructions: ${error.stack || error}\n`);
    process.exitCode = 1;
  }

  if (cpu.reason && !cpu.reason.startsWith('first frame')) {
    process.stderr.write(`vm.js: ${cpu.reason}\n`);
